package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;

/** One native entry point for Android Share/Open with; original grants stay on this task. */
public final class IncomingActivity extends WorkspaceActivity {
    static final int SAVE=93;final List<Uri> files=new ArrayList<>();int page;Uri saving;String text="";
    String title(){return "Receber ficheiros";}
    static List<Uri> streams(Intent input){LinkedHashSet<Uri> found=new LinkedHashSet<>();if(input==null)return new ArrayList<>();if(Intent.ACTION_VIEW.equals(input.getAction()))add(found,input.getData());else if(Intent.ACTION_SEND.equals(input.getAction())||Intent.ACTION_SEND_MULTIPLE.equals(input.getAction())){Object one=input.getParcelableExtra(Intent.EXTRA_STREAM);if(one instanceof Uri)add(found,(Uri)one);ArrayList<Uri> many=null;if(Intent.ACTION_SEND_MULTIPLE.equals(input.getAction()))many=input.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(many!=null)for(Uri uri:many)add(found,uri);ClipData clips=input.getClipData();if(clips!=null)for(int i=0;i<clips.getItemCount();i++)add(found,clips.getItemAt(i).getUri());}return new ArrayList<>(found);}
    static void add(Set<Uri> list,Uri uri){if(uri!=null&&("content".equals(uri.getScheme())||"file".equals(uri.getScheme())))list.add(uri);}
    int rejected;
    public void onCreate(Bundle state){try{List<Uri> received=streams(getIntent());for(Uri uri:received)if(IncomingUris.acceptable(this,uri))files.add(uri);rejected=received.size()-files.size();CharSequence value=getIntent().getCharSequenceExtra(Intent.EXTRA_TEXT);if(value!=null)text=AudioTitles.limit(value.toString(),20000,60000);}catch(RuntimeException e){text="Ficheiros de partilha inválidos.";}if(state!=null){page=Math.max(0,state.getInt("page"));String uri=state.getString("saving");if(uri!=null)saving=Uri.parse(uri);}super.onCreate(state);}
    void load(){content.removeAllViews();if(!text.isEmpty()){TextView shared=label(text,16);shared.setTextIsSelectable(true);content.addView(shared);}if(rejected>0)note(rejected+" "+AppLanguage.text(this,"ficheiro(s) recusado(s): localização privada ou sem autorização de acesso."));
if(files.isEmpty()){if(text.isEmpty()&&rejected==0)note("Nenhum ficheiro recebido.");return;}note(files.size()+" "+AppLanguage.text(this,"ficheiros recebidos"));action("Importar livros recebidos",()->ImportWork.enqueue(this,new ArrayList<>(files),0,true));for(int n=page*20;n<Math.min(files.size(),page*20+20);n++){final Uri uri=files.get(n);row("document",uri.getLastPathSegment()==null?"Ficheiro":uri.getLastPathSegment(),null,()->menu(uri));}pager(page,(page+1)*20<files.size(),()->{page--;load();},()->{page++;load();});if(files.size()==1&&page==0&&Intent.ACTION_VIEW.equals(getIntent().getAction())&&!getIntent().getBooleanExtra("routed",false)){getIntent().putExtra("routed",true);menu(files.get(0));}}
    static String[] metadata(Context c,Uri uri){String name=uri.getLastPathSegment();try(android.database.Cursor row=c.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(row!=null&&row.moveToFirst()&&!row.isNull(0))name=row.getString(0);}catch(RuntimeException ignored){}if(name==null||name.trim().isEmpty())name="Ficheiro";String type=null;try{type=c.getContentResolver().getType(uri);}catch(RuntimeException ignored){}return new String[]{name,MediaFormats.mime(name,type)};}
    void menu(Uri uri){PlusUi.run(this,()->{String[] meta=metadata(this,uri);String name=meta[0],mime=meta[1];PlusUi.post(this,()->{UiPanel panel=new UiPanel(this,name,null,"document");if(ArchiveFiles.accepts(name))panel.action("folder","Extrair no Seeky",null,false,()->{try{Uri shared=readable(uri,name,mime);Intent target=IncomingUris.sign(this,new Intent(this,MainActivity.class)).setDataAndType(shared,mime).putExtra("archive_uri",shared.toString()).putExtra("archive_name",name).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);target.setClipData(ClipData.newRawUri(name,shared));startActivity(target);}catch(Exception e){PlusUi.error(this,e);}});if(ApkInstallActivity.accepts(name,mime))panel.action("android","Instalar aplicação Android",null,false,()->ApkInstallActivity.open(this,uri,name));else if(!MediaFormats.kind(name,mime).equals("external"))panel.action("book","Abrir no Seeky",null,false,()->open(uri,name,mime));if(BookQuery.accepts(name,mime))panel.action("add","Adicionar à biblioteca",null,false,()->ImportWork.enqueue(this,Collections.singletonList(uri),0,true));panel.action("download","Guardar uma cópia",null,false,()->{saving=uri;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name),SAVE);}catch(Exception e){PlusUi.error(this,e);}});panel.action("arrow","Abrir noutra aplicação",null,false,()->external(uri,name,mime));panel.show();});});}
    void open(Uri uri,String name,String mime){try{Uri shared=readable(uri,name,mime);Intent target=new Intent(this,ReaderActivity.class).setDataAndType(shared,mime).putExtra("name",name).putExtra("full_screen",true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);target.setClipData(ClipData.newRawUri(name,shared));startActivity(target);}catch(Exception e){PlusUi.error(this,e);}}
    Uri readable(Uri uri,String name,String mime)throws IOException{if(!"file".equals(uri.getScheme()))return uri;if(!StorageAccess.allowed(this,new File(uri.getPath())))throw new IOException("Ficheiro sem acesso autorizado.");Catalog.Entry entry=new Catalog.Entry();entry.uri=uri.toString();entry.name=name;entry.mime=mime;return StorageAccess.shareUri(this,entry);}
    void external(Uri uri,String name,String mime){try{Uri shared=readable(uri,name,mime);Intent target=new Intent(Intent.ACTION_VIEW).setDataAndType(shared,mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);target.setClipData(ClipData.newRawUri(name,shared));Intent chooser=Intent.createChooser(target,AppLanguage.text(this,"Abrir ficheiro"));chooser.putExtra(Intent.EXTRA_EXCLUDE_COMPONENTS,new ComponentName[]{new ComponentName(this,IncomingActivity.class)});startActivity(chooser);}catch(Exception e){PlusUi.error(this,e);}}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=SAVE||result!=RESULT_OK||data==null||data.getData()==null||saving==null)return;Uri source=saving,target=data.getData();saving=null;PlusUi.longRun(this,()->{try(InputStream in=ApkInstallActivity.openSource(this,source);OutputStream out=getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Destino indisponível.");byte[] buffer=new byte[65536];for(int n;(n=in.read(buffer))!=-1;)out.write(buffer,0,n);}PlusUi.post(this,()->PlusUi.toast(this,"Cópia guardada."));});}
    protected void onSaveInstanceState(Bundle state){state.putInt("page",page);if(saving!=null)state.putString("saving",saving.toString());super.onSaveInstanceState(state);}
}
